// Pins shared/scanAlignment.mjs to the canonical cross-language vectors in
// vps-system/scan-format/alignment-vectors.json (generated by the Python
// reference; also checked by the Swift and Python test suites), and checks
// GeoJSON transformation + group-file parsing.
import { readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { applyXY, applyXZ, inverseXZ, parseGroupAlignment, alignmentFor, transformGeoJSON } from '../shared/scanAlignment.mjs';

const here = dirname(fileURLToPath(import.meta.url));
let passed = 0;
const check = (cond, msg) => { if (!cond) { console.error('FAIL', msg); process.exit(1); } passed++; };

// 1) canonical vectors (sibling repo, same relative layout as live-pose-smoke's assumptions)
const vectorsPath = resolve(here, '../../vps-system/scan-format/alignment-vectors.json');
if (existsSync(vectorsPath)) {
  const doc = JSON.parse(await readFile(vectorsPath, 'utf-8'));
  check(doc.format === 'scan-alignment-vectors-v1', 'vectors format');
  const tol = doc.tolerance ?? 1e-5;
  for (const c of doc.cases) {
    const [x, z] = applyXZ(c.alignment, c.arkit_xz[0], c.arkit_xz[1]);
    check(Math.abs(x - c.expected_arkit_xz[0]) < tol && Math.abs(z - c.expected_arkit_xz[1]) < tol, `applyXZ ${JSON.stringify(c.alignment)}`);
    const [bx, bz] = inverseXZ(c.alignment, x, z);
    check(Math.abs(bx - c.arkit_xz[0]) < tol && Math.abs(bz - c.arkit_xz[1]) < tol, 'inverseXZ round trip');
    const [sx, sy] = applyXY(c.alignment, c.slice_xy[0], c.slice_xy[1]);
    check(Math.abs(sx - c.expected_slice_xy[0]) < tol && Math.abs(sy - c.expected_slice_xy[1]) < tol, 'applyXY matches slice-plane form');
  }
  console.log(`vectors: ${doc.cases.length} cases ok`);
} else {
  console.log(`vectors file not found (${vectorsPath}) -- skipping canonical check`);
}

// 2) group file parsing + GeoJSON transform
const group = parseGroupAlignment({
  format: 'scan-group-alignment-v1', reference: 'scan_A', group: 'g',
  alignments: { scan_B: { offsetX: 2, offsetZ: -1, yawRadians: Math.PI / 2, method: 'pins' } },
});
check(alignmentFor(group, 'scan_A').yawRadians === 0, 'reference is identity');
check(alignmentFor(group, 'scan_B').method === 'pins', 'method kept');
let threw = false; try { alignmentFor(group, 'scan_Z'); } catch { threw = true; } check(threw, 'unknown scan throws');
threw = false; try { parseGroupAlignment({ format: 'nope' }); } catch { threw = true; } check(threw, 'wrong format throws');

const fc = { type: 'FeatureCollection', features: [
  { type: 'Feature', properties: { category: 'wall' }, geometry: { type: 'LineString', coordinates: [[1, 0], [1, 2]] } },
  { type: 'Feature', properties: { category: 'furniture' }, geometry: { type: 'Polygon', coordinates: [[[0, 0], [1, 0], [1, 1], [0, 0]]] } },
] };
const out = transformGeoJSON(fc, alignmentFor(group, 'scan_B'));
// yaw 90deg CCW in the slice plane, then translate (offsetX, -offsetZ) = (2, 1): (1,0) -> (0,1)+(2,1) = (2,2); (1,2) -> (-2,1)+(2,1) = (0,2)
const seg = out.features[0].geometry.coordinates;
check(Math.abs(seg[0][0] - 2) < 1e-9 && Math.abs(seg[0][1] - 2) < 1e-9, 'wall start transformed');
check(Math.abs(seg[1][0] - 0) < 1e-9 && Math.abs(seg[1][1] - 2) < 1e-9, 'wall end transformed');
check(fc.features[0].geometry.coordinates[0][0] === 1, 'input not mutated');
check(out.features[1].geometry.coordinates[0].length === 4, 'polygon ring length preserved');



// 3) --room-walls: a room outline becomes one thickened wall block per edge
{
  const { roomOutlineToWallBlocks } = await import('./import-scan-to-map-studio.mjs');
  const room = { type: 'Feature', properties: { category: 'room', area_m2: 6 }, geometry: { type: 'Polygon', coordinates: [[[0, 0], [3, 0], [3, 2], [0, 2], [0, 0]]] } };
  const blocks = roomOutlineToWallBlocks(room, { wallThickness: 0.2, baseProps: { room: 'r' } });
  check(blocks.length === 4, 'one wall block per outline edge');
  check(blocks.every((b) => b.properties.kind === 'block' && b.properties.category === 'wall' && b.properties.derived_from === 'room-outline'), 'wall blocks tagged');
  check(blocks.every((b) => b.geometry.coordinates[0].length === 5), 'wall rings closed (5 points)');
  const first = blocks[0].geometry.coordinates[0];
  const ys = first.map((p) => p[1]);
  check(Math.abs(Math.max(...ys) - 0.1) < 1e-9 && Math.abs(Math.min(...ys) + 0.1) < 1e-9, 'bottom edge buffered ±thickness/2');
  check(Math.abs(blocks[1].properties.length_m - 2) < 1e-9, 'edge length recorded');
}
console.log(`all scan-alignment smoke checks passed (${passed})`);
